//! CoreBridge — P/Invoke imports for Download Core C ABI.
//!
//! Generated bindings for the Download Core cdylib.
//! In production these are generated by csbindgen.
//! This hand-written stub mirrors the csbindgen output for bootstrapping.
//!
//! csbindgen build command:
//! ```ignore
//! csbindgen::Builder::default()
//!     .input_extern_file("src/cabi.rs")
//!     .csharp_dll_name("download_core")
//!     .generate_csharp_file("../winui-shell/Phlegethon/bindings/CoreBindings.g.cs")
//!     .expect("csbindgen generation failed");
//! ```

using System;
using System.Runtime.InteropServices;

namespace Phlegethon.Services;

/// <summary>
/// C ABI bridge to the Download Core Rust cdylib (download_core.dll).
/// Every function returns 0 on success, -1 on error.
/// Error details are written into the provided error buffer.
/// </summary>
internal static class CoreBridge
{
    private const string DllName = "download_core";

    // -----------------------------------------------------------------------
    // Core lifecycle
    // -----------------------------------------------------------------------

    /// <summary>
    /// Create a new Download Core instance.
    /// Returns an opaque handle. Must be freed with core_destroy.
    /// </summary>
    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl)]
    public static extern IntPtr core_create();

    /// <summary>
    /// Destroy a Core instance. Safe to call with IntPtr.Zero.
    /// </summary>
    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl)]
    public static extern void core_destroy(IntPtr handle);

    /// <summary>
    /// Set the Library Root directory.
    /// </summary>
    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_set_library_root(
        IntPtr handle,
        string path,
        IntPtr errorBuf,
        int errorBufLen);

    // -----------------------------------------------------------------------
    // Enqueue
    // -----------------------------------------------------------------------

    /// <summary>
    /// Enqueue a URL. Writes JSON result to outJsonBuf.
    /// </summary>
    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_enqueue(
        IntPtr handle,
        string url,
        IntPtr outJsonBuf,
        int outBufLen,
        IntPtr errorBuf,
        int errorBufLen);

    // -----------------------------------------------------------------------
    // Probe-then-Confirm
    // -----------------------------------------------------------------------

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_probe(
        IntPtr handle,
        string url,
        IntPtr outJsonBuf,
        int outBufLen,
        IntPtr errorBuf,
        int errorBufLen);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_confirm_probe_selection(
        IntPtr handle,
        string selectionJson,
        IntPtr outJsonBuf,
        int outBufLen,
        IntPtr errorBuf,
        int errorBufLen);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_preview_probe_destination(
        IntPtr handle,
        string selectionJson,
        IntPtr outJsonBuf,
        int outBufLen,
        IntPtr errorBuf,
        int errorBufLen);

    // -----------------------------------------------------------------------
    // Lifecycle commands
    // -----------------------------------------------------------------------

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_pause_job(
        IntPtr handle,
        string jobId,
        IntPtr errorBuf,
        int errorBufLen);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_resume_job(
        IntPtr handle,
        string jobId,
        IntPtr errorBuf,
        int errorBufLen);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_retry_job(
        IntPtr handle,
        string jobId,
        IntPtr errorBuf,
        int errorBufLen);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_discard_job(
        IntPtr handle,
        string jobId,
        IntPtr errorBuf,
        int errorBufLen);

    // -----------------------------------------------------------------------
    // Processing
    // -----------------------------------------------------------------------

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_process_pending(
        IntPtr handle,
        IntPtr errorBuf,
        int errorBufLen);

    // -----------------------------------------------------------------------
    // Events
    // -----------------------------------------------------------------------

    /// <summary>
    /// Drain pending events as a JSON array. Returns the number of events drained, or -1 on error.
    /// </summary>
    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_drain_events_json(
        IntPtr handle,
        IntPtr outJsonBuf,
        int outBufLen);

    // -----------------------------------------------------------------------
    // Bandwidth caps
    // -----------------------------------------------------------------------

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl)]
    public static extern void core_set_global_bandwidth_cap(
        IntPtr handle,
        ulong cap);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl)]
    public static extern void core_remove_global_bandwidth_cap(
        IntPtr handle);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_set_job_bandwidth_cap(
        IntPtr handle,
        string jobId,
        ulong cap,
        IntPtr errorBuf,
        int errorBufLen);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_remove_job_bandwidth_cap(
        IntPtr handle,
        string jobId,
        IntPtr errorBuf,
        int errorBufLen);

    // -----------------------------------------------------------------------
    // Mirror sets
    // -----------------------------------------------------------------------

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_add_job_mirror(
        IntPtr handle,
        string jobId,
        string url,
        IntPtr errorBuf,
        int errorBufLen);

    [DllImport(DllName, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Ansi)]
    public static extern int core_job_mirrors(
        IntPtr handle,
        string jobId,
        IntPtr outJsonBuf,
        int outBufLen,
        IntPtr errorBuf,
        int errorBufLen);
}

// ---------------------------------------------------------------------------
// Safe wrapper
// ---------------------------------------------------------------------------

/// <summary>
/// Safe managed wrapper around the Download Core C ABI.
/// Manages handle lifetime, buffer allocation, and error handling.
/// </summary>
public class CoreHandle : IDisposable
{
    private IntPtr _handle;
    private bool _disposed;

    public CoreHandle()
    {
        _handle = CoreBridge.core_create();
        if (_handle == IntPtr.Zero)
            throw new InvalidOperationException("Failed to create Download Core instance");
    }

    public void Dispose()
    {
        if (!_disposed)
        {
            CoreBridge.core_destroy(_handle);
            _handle = IntPtr.Zero;
            _disposed = true;
        }
    }

    public IntPtr Handle => _handle;

    // -----------------------------------------------------------------------
    // Safe invocation helpers
    // -----------------------------------------------------------------------

    private const int BufSize = 65536;

    private static unsafe string CallWithJsonResult(Func<IntPtr, IntPtr, int, IntPtr, int, int> fn, IntPtr handle, string? arg1 = null)
    {
        byte* outBuf = stackalloc byte[BufSize];
        byte* errBuf = stackalloc byte[1024];
        var outPtr = new IntPtr(outBuf);
        var errPtr = new IntPtr(errBuf);

        int result;
        if (arg1 != null)
            result = fn(handle, arg1, outPtr, BufSize, errPtr, 1024);
        else
            result = fn(handle, outPtr, BufSize, errPtr, 1024);

        if (result != 0)
        {
            var errMsg = Marshal.PtrToStringAnsi(errPtr) ?? "unknown error";
            throw new InvalidOperationException($"Core call failed: {errMsg}");
        }

        return Marshal.PtrToStringAnsi(outPtr) ?? "{}";
    }

    public string Enqueue(string url)
    {
        return CallWithJsonResult(
            (h, o, ol, e, el) => CoreBridge.core_enqueue(h, url, o, ol, e, el),
            _handle);
    }

    public string Probe(string url)
    {
        return CallWithJsonResult(
            (h, o, ol, e, el) => CoreBridge.core_probe(h, url, o, ol, e, el),
            _handle, url);
    }

    public string ConfirmProbeSelection(string selectionJson)
    {
        return CallWithJsonResult(
            (h, o, ol, e, el) => CoreBridge.core_confirm_probe_selection(h, selectionJson, o, ol, e, el),
            _handle, selectionJson);
    }

    public string PreviewProbeDestination(string selectionJson)
    {
        return CallWithJsonResult(
            (h, o, ol, e, el) => CoreBridge.core_preview_probe_destination(h, selectionJson, o, ol, e, el),
            _handle, selectionJson);
    }

    public void PauseJob(string jobId)
    {
        ThrowOnError(CoreBridge.core_pause_job(_handle, jobId, IntPtr.Zero, 0));
    }

    public void ResumeJob(string jobId)
    {
        ThrowOnError(CoreBridge.core_resume_job(_handle, jobId, IntPtr.Zero, 0));
    }

    public void RetryJob(string jobId)
    {
        ThrowOnError(CoreBridge.core_retry_job(_handle, jobId, IntPtr.Zero, 0));
    }

    public void DiscardJob(string jobId)
    {
        ThrowOnError(CoreBridge.core_discard_job(_handle, jobId, IntPtr.Zero, 0));
    }

    public void SetLibraryRoot(string path)
    {
        unsafe
        {
            byte* errBuf = stackalloc byte[1024];
            var errPtr = new IntPtr(errBuf);
            int result = CoreBridge.core_set_library_root(_handle, path, errPtr, 1024);
            if (result != 0)
            {
                var errMsg = Marshal.PtrToStringAnsi(errPtr) ?? "unknown error";
                throw new InvalidOperationException($"Failed to set library root: {errMsg}");
            }
        }
    }

    public void ProcessPending()
    {
        ThrowOnError(CoreBridge.core_process_pending(_handle, IntPtr.Zero, 0));
    }

    public string DrainEvents()
    {
        return CallWithJsonResult(
            (h, o, ol, e, el) => CoreBridge.core_drain_events_json(h, o, ol),
            _handle);
    }

    private static void ThrowOnError(int result)
    {
        if (result != 0)
            throw new InvalidOperationException("Core command failed");
    }
}
